import React from 'react';
import { motion } from 'framer-motion';
import { Code2, PenTool, Globe, Rocket, Shield, HardDrive } from 'lucide-react';

const services = [
    { id: 1, title: "Custom Software", desc: "Tailored solutions built with precision and modern tech stacks.", icon: <Code2 />, size: "span-8" },
    { id: 2, title: "Product Design", desc: "High-end UI/UX focus.", icon: <PenTool />, size: "span-4" },
    { id: 3, title: "Cloud Scale", desc: "Reliable infrastructure.", icon: <HardDrive />, size: "span-4" },
    { id: 4, title: "Global Deploy", desc: "Zero-latency worldwide connectivity and delivery.", icon: <Globe />, size: "span-8" },
    { id: 5, title: "AI Integration", desc: "Next-gen automation.", icon: <Rocket />, size: "span-6" },
    { id: 6, title: "Cyber Security", desc: "Enterprise protection.", icon: <Shield />, size: "span-6" },
];

function Services() {
    return (
        <section className="services-section" id="services">
            <span className="section-label">Core Capabilities</span>
            <div className="bento-grid">
                {services.map((s) => (
                    <motion.div
                        key={s.id}
                        initial={{ opacity: 0, scale: 0.95 }}
                        whileInView={{ opacity: 1, scale: 1 }}
                        viewport={{ once: true }}
                        whileHover={{ y: -5 }}
                        className={`bento-item ${s.size}`}
                    >
                        <div className="bento-icon">{s.icon}</div>
                        <h3 className="bento-title">{s.title}</h3>
                        <p className="bento-desc">{s.desc}</p>
                    </motion.div>
                ))}
            </div>
        </section>
    );
}

export default Services;
